descriptor.templateCss:
.balance-card-container {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 14px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #64B856;
  padding: 16px 22px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
  overflow: hidden;
  transition: border-top-color 0.3s ease;
}

.balance-card-container.surplus {
  border-top-color: #06b6d4;
}

.balance-card-container.deficit {
  border-top-color: #f59e0b;
}

.balance-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 24px;
}

.balance-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
  white-space: nowrap;
}

.balance-icon {
  font-size: 16px;
}

.balance-status-badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  padding: 2px 10px;
  border-radius: 20px;
  white-space: nowrap;
  transition: all 0.3s ease;
}

.balance-status-badge.surplus {
  color: #06b6d4;
  border: 1.5px solid #06b6d4;
  background: rgba(6, 182, 212, 0.1);
}

.balance-status-badge.deficit {
  color: #f59e0b;
  border: 1.5px solid #f59e0b;
  background: rgba(245, 158, 11, 0.1);
}

.balance-metric-body {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 6px 0;
  min-height: 40px;
}

.metric-value {
  font-size: 40px;
  font-weight: 800;
  color: #06b6d4;
  line-height: 1;
  transition: color 0.3s ease;
}

.metric-value.deficit {
  color: #f59e0b;
}

.metric-unit {
  font-size: 20px;
  font-weight: 600;
  color: #94a3b8;
  white-space: nowrap;
}

.balance-divider {
  width: 100%;
  height: 1px;
  background: rgba(148, 163, 184, 0.15);
  margin: 8px 0 10px 0;
}

.balance-card-footer {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  min-height: 38px;
}

.footer-left {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

.footer-left .footer-label {
  font-size: 13px;
  font-weight: 500;
  color: #94a3b8;
  white-space: nowrap;
}

.footer-left .footer-subtext {
  font-size: 12px;
  color: #556987;
  margin-top: 3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.footer-right {
  display: flex;
  align-items: flex-end;
}

.footer-right .footer-value {
  font-size: 14px;
  font-weight: 600;
  color: #94a3b8;
  white-space: nowrap;
}

descriptor.controllerScript:
self.onInit = function() {
  self.onDataUpdated();
};

self.onDataUpdated = function() {
  var data = self.ctx.data;
  var solar = 0.0;
  var bess = 0.0;
  var load = 0.0;

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var lastVal = item.data[item.data.length - 1][1];
        var num = parseFloat(lastVal);
        var keyName = (item.dataKey.label || item.dataKey.name || "").toLowerCase();

        if (!isNaN(num)) {
          if (keyName.indexOf("solar") !== -1 || i === 0) {
            solar = num;
          } else if (keyName.indexOf("bess") !== -1 || i === 1) {
            bess = num;
          } else if (keyName.indexOf("carga") !== -1 || keyName.indexOf("demanda") !== -1 || i === 2) {
            load = num;
          }
        }
      }
    }
  }

  // En microrred real:
  // Si BESS descarga (bess < 0 o suministra a la carga), actua como fuente generadora
  var genBess = bess < 0 ? Math.abs(bess) : 0.0;
  var cargaBess = bess > 0 ? bess : 0.0;
  var totalGen = solar + genBess;
  var totalLoad = load + cargaBess;
  var netBalance = totalGen - totalLoad;

  var isBalanced = Math.abs(netBalance) <= 20.0;
  var isSurplus = netBalance > 20.0;
  var statusBadge = isBalanced ? "AUTÓNOMO" : (isSurplus ? "SUPERÁVIT" : "DÉFICIT");
  var modeClass = (isBalanced || isSurplus) ? "surplus" : "deficit";
  var netSign = netBalance > 0 ? "+" : "";
  var netString = isBalanced ? "±0.0" : (netSign + netBalance.toFixed(1));

  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (container) {
    var card = container.querySelector('#balance-card');
    if (card) {
      card.className = "balance-card-container " + modeClass;
    }

    var elNet = container.querySelector('#balance-net-value');
    if (elNet) {
      elNet.textContent = netString;
      elNet.className = "metric-value " + (modeClass === 'surplus' ? '' : 'deficit');
    }

    var elBadge = container.querySelector('#balance-status-badge');
    if (elBadge) {
      elBadge.textContent = statusBadge;
      elBadge.className = "balance-status-badge " + modeClass;
    }

    var elSubtext = container.querySelector('#balance-subtext');
    if (elSubtext) {
      var bessLabel = bess < 0 ? ("BESS: ▼ " + Math.abs(bess).toFixed(1)) : ("BESS: ▲ " + bess.toFixed(1));
      elSubtext.textContent = "Solar: " + solar.toFixed(1) + " | " + bessLabel + " kW";
    }

    var elLoad = container.querySelector('#balance-load-value');
    if (elLoad) {
      elLoad.textContent = "Carga: " + load.toFixed(1) + " kW";
    }
  }
};

self.onDestroy = function() {};
